#!/usr/bin/env python3
"""Writes docs/reference/cli.md from `wasmkeep --help`, recursively.

    scripts/cli-reference.py BINARY            rewrite the page
    scripts/cli-reference.py BINARY --check    fail when the page is stale

Use scripts/cli-reference.sh, which builds the binary first. The page is
generated: change a flag's help text in the code, not the page.
"""
import pathlib
import re
import subprocess
import sys

root = pathlib.Path(__file__).resolve().parent.parent
page = root / 'docs/reference/cli.md'

HEADER = """# CLI reference

<!-- Generated by scripts/cli-reference.sh from `wasmkeep --help`: do not edit by hand. -->

Every command and flag of `wasmkeep`, with its default and a one-line meaning. The one-line
meaning is the first sentence of the flag's help; `wasmkeep <command> --help` prints the whole
text. This page is generated from the built binary, and `./scripts/cli-reference.sh --check` fails
when it is stale.

For how the flags fit together, see [Running a cluster](../cluster.md),
[the node file](node-file.md), [Socket admission options](socket-limits.md) and
[Going to production](../tutorials/going-to-production.md). For what to do when a node refuses to
start, see [Troubleshooting](../troubleshooting.md).

"""

# Defaults that differ from machine to machine, shown as a rule instead.
DEFAULT_OVERRIDES = {'--malloc-arena-max': 'cores, clamped to 2..8'}


def help_of(binary, path):
    out = subprocess.run([binary, *path, '--help'], check=True, capture_output=True, text=True,
                         env={'COLUMNS': '100000', 'NO_COLOR': '1', 'PATH': '/usr/bin:/bin'}).stdout
    return out


def sections(text):
    """The about text, usage line and named sections of a help page."""
    lines = text.split('\n')
    about, usage, named, current = [], '', {}, None
    for line in lines:
        if line.startswith('Usage: '):
            usage = line[len('Usage: '):]
            current = None
        elif re.match(r'^[A-Z][A-Za-z ]*:$', line):
            current = line[:-1]
            named[current] = []
        elif current is not None:
            named[current].append(line)
        elif not usage and line.strip():
            about.append(line.strip())
    return ' '.join(about), usage, named


def first_sentence(text, limit=240):
    text = re.sub(r'\s+', ' ', text).strip()
    protected = re.sub(r'\b(e\.g|i\.e|etc|vs)\.', lambda m: m.group(0).replace('.', '\x00'), text)
    m = re.search(r'(?<=[A-Za-z0-9`)\x27"])\.(?:\s|$)', protected)
    out = protected[:m.start() + 1] if m else protected
    out = out.replace('\x00', '.').rstrip()
    if len(out) > limit:
        out = out[:limit].rsplit(' ', 1)[0].rstrip(',;:') + ' ...'
    return out


def parse_options(lines):
    """Option entries: (flag line, meaning, default, possible values)."""
    entries, cur = [], None
    for line in lines:
        indent = len(line) - len(line.lstrip())
        if line.strip() and indent <= 6 and line.lstrip().startswith('-'):
            cur = {'head': line.strip(), 'text': [], 'default': None, 'values': None, 'para': True, 'bullets': []}
            entries.append(cur)
        elif cur is not None and line.strip():
            s = line.strip()
            if s.startswith('[default: '):
                cur['default'] = s[len('[default: '):-1]
            elif s.startswith('[possible values: '):
                cur['values'] = s[len('[possible values: '):-1]
            elif s == 'Possible values:':
                cur['para'] = False
            elif s.startswith('- ') and not cur['para']:
                cur['bullets'].append(s[2:].split(':', 1)[0])
            elif cur['para']:
                cur['text'].append(s)
        elif cur is not None and not line.strip() and cur['text']:
            cur['para'] = False
    return entries


def parse_arguments(lines):
    entries, cur = [], None
    for line in lines:
        indent = len(line) - len(line.lstrip())
        if line.strip() and indent <= 2:
            cur = {'head': line.strip(), 'text': [], 'para': True}
            entries.append(cur)
        elif cur is not None and line.strip() and cur['para']:
            cur['text'].append(line.strip())
        elif cur is not None and not line.strip() and cur['text']:
            cur['para'] = False
    return entries


def subcommands(lines):
    names = []
    for line in lines:
        m = re.match(r'^  ([a-z][a-z0-9-]*)\s{2,}(.*)$', line)
        if m and m.group(1) != 'help':
            names.append(m.group(1))
    return names


def prose(text):
    """Text outside code spans, with placeholders such as <NAME> put in code spans so they are not HTML."""
    parts = text.split('`')
    for i in range(0, len(parts), 2):
        parts[i] = re.sub(r'([^\s(]*<[^<>\s]+>[^\s),;]*)', lambda m: '`' + m.group(1) + '`', parts[i])
    return '`'.join(parts)


def cell(text):
    return text.replace('|', '\\|')


def flag_name(head):
    return re.findall(r'--[a-z0-9-]+', head)[0]


def render(binary, path, globals_, out):
    text = help_of(binary, path)
    about, usage, named = sections(text)
    level = min(len(path) + 2, 4)
    title = ' '.join(['wasmkeep', *path])
    out.append(f"{'#' * level} `{title}`\n")
    if about:
        out.append(prose(first_sentence(about, 400)) + '\n')
    out.append(f'Usage: `{usage.replace("wasmkeep", "wasmkeep", 1)}`\n')
    args = parse_arguments(named.get('Arguments', []))
    opts = [o for o in parse_options(named.get('Options', []))
            if flag_name(o['head']) not in ('--help', '--version') and (not path or flag_name(o['head']) not in globals_)]
    if args or opts:
        out.append('| Flag or argument | Default | Meaning |\n|---|---|---|')
        for a in args:
            out.append(f"| `{cell(a['head'])}` | | {cell(prose(first_sentence(re.sub(r'\s*\[(default|possible values): [^\]]*\]', '', ' '.join(a['text'])))))} |")
        for o in opts:
            name = flag_name(o['head'])
            default = DEFAULT_OVERRIDES.get(name, o['default'])
            shown = f'`{cell(default)}`' if default else ''
            values = o['values'] or ', '.join(o['bullets'])
            full = ' '.join(o['text'])
            # Short help puts the default and the values inside the text.
            m = re.search(r'\s*\[default: ([^\]]*)\]', full)
            if m and not default:
                default = m.group(1)
                shown = f'`{cell(default)}`'
            m = re.search(r'\s*\[possible values: ([^\]]*)\]', full)
            if m and not values:
                values = m.group(1)
            full = re.sub(r'\s*\[(default|possible values): [^\]]*\]', '', full)
            meaning = first_sentence(full)
            if values:
                meaning += f' One of: {values}.'
            out.append(f"| `{cell(o['head'])}` | {shown} | {cell(prose(meaning))} |")
        out.append('')
    for sub in subcommands(named.get('Commands', [])):
        render(binary, [*path, sub], globals_, out)


def generate(binary):
    text = help_of(binary, [])
    _, _, named = sections(text)
    globals_ = {flag_name(o['head']) for o in parse_options(named.get('Options', []))}
    out = []
    render(binary, [], globals_, out)
    body = '\n'.join(out)
    # No machine-specific paths in a published page.
    for forbidden in ('/home/', '/Users/'):
        if forbidden in body:
            sys.exit(f'generated page contains {forbidden}: a default depends on the machine')
    return HEADER + 'Options before the command (`--malloc-arena-max`) apply to every command and are listed once, under `wasmkeep`.\n\n' + body.rstrip() + '\n'


def main():
    if len(sys.argv) < 2:
        sys.exit(__doc__)
    new = generate(sys.argv[1])
    if '--check' in sys.argv[2:]:
        old = page.read_text() if page.exists() else ''
        if old != new:
            print('docs/reference/cli.md is stale: run ./scripts/cli-reference.sh', file=sys.stderr)
            sys.exit(1)
        print('docs/reference/cli.md is up to date')
    else:
        page.write_text(new)
        print(f'wrote {page.relative_to(root)}')


main()
